import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"Agnes AI","description":"Agnes AI 無料マルチモーダル API：公式入口、Free Access で Key 取得、テキスト／画像／動画モデル一覧、MiniTavern での記入。","frontmatter":{"title":"Agnes AI","description":"Agnes AI 無料マルチモーダル API：公式入口、Free Access で Key 取得、テキスト／画像／動画モデル一覧、MiniTavern での記入。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"Agnes AI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Agnes AI 無料マルチモーダル API：公式入口、Free Access で Key 取得、テキスト／画像／動画モデル一覧、MiniTavern での記入。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/free-cloud/agnes-ai"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/free-cloud/agnes-ai"}]]},"headers":[],"relativePath":"ja/free-cloud/agnes-ai.md","filePath":"ja/free-cloud/agnes-ai.md","lastUpdated":1787224147000}'),n={name:"ja/free-cloud/agnes-ai.md"};function d(s,e,i,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h1><p>シンガポール Sapiens AI 傘下のマルチモーダルモデルサービス：同一の OpenAI 互換ゲートウェイで<strong>テキスト対話、画像生成、動画</strong>をカバー。**Free Access（無料体験帯）**があり、有料 Key なしで開聊と試生図に向く；枠と限速はコンソール準拠。</p><h2 id="公式と入口" tabindex="-1">公式と入口 <a class="header-anchor" href="#公式と入口" aria-label="Permalink to &quot;公式と入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>リソース</th><th>アドレス</th></tr></thead><tbody><tr><td>国際サイト</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a></td></tr><tr><td>中国サイト</td><td><a href="https://agnes-ai.cn/" target="_blank" rel="noreferrer">agnes-ai.cn</a></td></tr><tr><td>API コンソール（登録／Key）</td><td><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>開発者ドキュメント</td><td><a href="https://agnes-ai.com/en/docs/overview" target="_blank" rel="noreferrer">agnes-ai.com/en/docs/overview</a></td></tr><tr><td>モデル一覧（GitHub）</td><td><a href="https://github.com/AgnesAI-Labs/AgnesAI-Models" target="_blank" rel="noreferrer">AgnesAI-Labs/AgnesAI-Models</a></td></tr><tr><td>API Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr></tbody></table><p>地域に応じて国際／中国サイトを選ぶ；<strong>API Key と Base URL はコンソール／ドキュメントの現行表示を正</strong>とする。</p><h2 id="無料の取得-free-access" tabindex="-1">無料の取得（Free Access） <a class="header-anchor" href="#無料の取得-free-access" aria-label="Permalink to &quot;無料の取得（Free Access）&quot;">​</a></h2><ol><li><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a> で登録・ログイン（多くはメール；カード要否はページ準拠）。</li><li>開発者コンソール → <strong>API Keys</strong> → 作成して Key をコピー（多くは <code>sk-</code> 始まり）。</li><li>MiniTavern で <strong>カスタム (OpenAI)</strong>（チャット）または <strong>カスタム (OpenAI Images)</strong>（画像）に Base URL と Key を記入（下記）。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td>無料方式</td><td><strong>Free Access</strong>：中核 Flash 系列を無料呼び出し可（RPM／fair-use 限速）、個人試用と demo 向き</td></tr><tr><td>有料アップグレード</td><td><strong>Token Plan</strong>：より高い TPS／月枠、本番と高頻度 Agent 向け（必須ではない）</td></tr><tr><td>限速参考（無料帯）</td><td>テキスト約 <strong>20 RPM</strong>；画像は解像度別（1K 約 20 RPM、高いほど厳）；動画約 <strong>1 RPM</strong>（公式 <a href="https://agnes-ai.com/en/docs/tokenplan" target="_blank" rel="noreferrer">Token Plan FAQ</a>）</td></tr><tr><td>カード紐付け</td><td>Free Access は通常強制しない；商用やより高い枠は Token Plan を検討</td></tr></tbody></table><blockquote><p>政策は変わります。コンソールで Token Plan 必須と出る、または 429 が返る場合は、公式とアカウント権限を正としてください。</p></blockquote><h2 id="モデル一覧" tabindex="-1">モデル一覧 <a class="header-anchor" href="#モデル一覧" aria-label="Permalink to &quot;モデル一覧&quot;">​</a></h2><p>公開ドキュメントとモデル一覧のよくある ID（<strong>大文字小文字区別</strong>）。Flash は多く無料帯；<strong>Pro</strong> 付きは一般に有料推論モデル。</p><h3 id="テキスト-対話-視覚理解" tabindex="-1">テキスト（対話／視覚理解） <a class="header-anchor" href="#テキスト-対話-視覚理解" aria-label="Permalink to &quot;テキスト（対話／視覚理解）&quot;">​</a></h3><p>Chat Completions：<code>POST /v1/chat/completions</code>。MiniTavern は <strong>カスタム (OpenAI)</strong>。</p><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>agnes-2.5-flash</code></td><td>推奨：対話、コーディング、ツール呼び出し、多轮と画像理解；コンテキスト約 512K</td></tr><tr><td><code>agnes-2.0-flash</code></td><td>前世代 Flash、互換の予備</td></tr><tr><td><code>agnes-2.5-pro</code> / <code>agnes-2.5-pro-alpha</code></td><td>有料推論帯（上級コーディング／科学推論など）、<strong>無料帯として使わない</strong></td></tr></tbody></table><h3 id="画像-文生図-図生図" tabindex="-1">画像（文生図／図生図） <a class="header-anchor" href="#画像-文生図-図生図" aria-label="Permalink to &quot;画像（文生図／図生図）&quot;">​</a></h3><p>Images：文生図と図生図はいずれも <code>POST /v1/images/generations</code>（図生図は body に <code>image</code>、OpenAI の <code>/images/edits</code> <strong>ではない</strong>）。MiniTavern は <strong>カスタム (OpenAI Images)</strong>、Base URL は同じく <code>https://apihub.agnes-ai.com/v1</code>；App はカスタムプロトコルをこの経路で送り、測連の参考図も generations へ。</p><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>agnes-image-2.1-flash</code></td><td>推奨：高情報密度の生図と編集、柔軟なサイズ</td></tr><tr><td><code>agnes-image-2.0-flash</code></td><td>文生図／図生図、URL または Base64 出力</td></tr></tbody></table><h3 id="動画-文生動画-図生動画" tabindex="-1">動画（文生動画／図生動画） <a class="header-anchor" href="#動画-文生動画-図生動画" aria-label="Permalink to &quot;動画（文生動画／図生動画）&quot;">​</a></h3><p>Videos：<code>POST /v1/videos</code>（非同期タスク）。よくある ID：</p><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>agnes-video-v2.0</code></td><td>文生動画、図生動画、多図／キーフレームなど</td></tr><tr><td><code>agnes-video-v2.5</code>（またはドキュメントの Video 2.5）</td><td>新世代動画インタフェース、<a href="https://agnes-ai.com/en/docs/agnes-video-v20" target="_blank" rel="noreferrer">公式動画ドキュメント</a> 準拠</td></tr></tbody></table><p>MiniTavern に <strong>現時点で内蔵の動画生成入口はない</strong>；上表は公式能力の対照用。チャットと画像は先に Flash テキスト／画像モデルでよい。</p><h2 id="minitavern-での記入" tabindex="-1">MiniTavern での記入 <a class="header-anchor" href="#minitavern-での記入" aria-label="Permalink to &quot;MiniTavern での記入&quot;">​</a></h2><p>一般手順は <a href="/ultra_guides/ja/manual/model-link">モデル接続</a>。</p><h3 id="チャット" tabindex="-1">チャット <a class="header-anchor" href="#チャット" aria-label="Permalink to &quot;チャット&quot;">​</a></h3><p>経路：<strong>設定 → モデル → モデル接続 → 新規</strong></p><ol><li>プラットフォーム <strong>カスタム (OpenAI)</strong></li><li>Base URL：<code>https://apihub.agnes-ai.com/v1</code></li><li>API Key を貼り付け</li><li>モデル ID に <code>agnes-2.5-flash</code>（またはコンソール一覧の他テキストモデル）</li><li><strong>テスト</strong> → 成功後にデフォルトへ</li></ol><h3 id="画像生成" tabindex="-1">画像生成 <a class="header-anchor" href="#画像生成" aria-label="Permalink to &quot;画像生成&quot;">​</a></h3><p>経路：<strong>設定 → 画像生成 → 画像接続</strong></p><ol><li>プラットフォーム <strong>カスタム (OpenAI Images)</strong></li><li>Base URL 同上</li><li>同一 Key；モデルは <code>agnes-image-2.1-flash</code> など</li><li>測連後に <code>/imagine</code> や画像入口で使用</li></ol><p>チャット接続と画像接続は分離可：例チャット <code>agnes-2.5-flash</code>、画像 <code>agnes-image-2.1-flash</code>。</p><h2 id="関連章" tabindex="-1">関連章 <a class="header-anchor" href="#関連章" aria-label="Permalink to &quot;関連章&quot;">​</a></h2><ul><li><a href="/ultra_guides/ja/free-cloud/">無料クラウド総覧</a> — 他社の無料／体験枠</li><li><a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料の画像生成</a></li><li><a href="/ultra_guides/ja/manual/model-link">モデル接続</a></li><li><a href="/ultra_guides/ja/local/image-gen/">画像モデル配備</a> — 本機 A1111 / ComfyUI</li></ul>',32)])])}const m=t(n,[["render",d]]);export{p as __pageData,m as default};
